import{_ as a,C as n,o,c as i,j as r,a as t,E as u,a2 as l}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Ouvrir un workspace","description":"","frontmatter":{"title":"Ouvrir un workspace"},"headers":[],"relativePath":"guide/start.md","filePath":"guide/start.md"}'),c={name:"guide/start.md"};function p(d,e,g,h,v,f){const s=n("Capture");return o(),i("div",null,[e[0]||(e[0]=r("h1",{id:"ouvrir-un-workspace",tabindex:"-1"},[t("Ouvrir un workspace "),r("a",{class:"header-anchor",href:"#ouvrir-un-workspace","aria-label":'Permalink to "Ouvrir un workspace"'},"​")],-1)),e[1]||(e[1]=r("p",null,[t("Le sélecteur est l'écran d'accueil d'Effortless : vous y arrivez à chaque lancement, une fois votre profil créé (au tout premier lancement, voir "),r("a",{href:"/Effortless/guide/first-run.html"},"Premier lancement"),t("), et chaque fois que vous cliquez sur l'icône de grille ou sur "),r("strong",null,"+"),t(" dans la barre du haut. Un workspace est un projet Effortless : vous venez ici pour en ouvrir un, en créer un ou reprendre un projet existant.")],-1)),u(s,{name:"selecteur",alt:"Le sélecteur de workspace : actions à gauche, liste des récents à droite"}),e[2]||(e[2]=l('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>En haut</strong> : le titre « Ouvrir un workspace » et le rappel « Un workspace = un projet Effortless. »</li><li><strong>À gauche</strong> : quatre actions — <strong>Ouvrir…</strong>, <strong>Créer…</strong>, <strong>Assistant de création</strong>, <strong>Reprendre un projet existant</strong> — et un champ de saisie de chemin.</li><li><strong>À droite</strong> : la liste <strong>Récents</strong>, regroupée par catégorie quand vous en avez déclaré (Atelier, Clients, Interne dans l&#39;exemple). Chaque carte indique le nom du projet, son chemin et sa « Dernière ouverture ». Tant que la liste est vide, l&#39;écran affiche « Aucun workspace récent. Ouvre ou crée un projet à gauche. »</li></ul><p>Les onglets, le thème et les préférences de la barre du haut sont décrits dans <a href="/Effortless/guide/window.html">Fenêtre, barres et systray</a>.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="ouvrir-un-projet-existant" tabindex="-1">Ouvrir un projet existant <a class="header-anchor" href="#ouvrir-un-projet-existant" aria-label="Permalink to &quot;Ouvrir un projet existant&quot;">​</a></h3><p>Cliquez sur <strong>Ouvrir…</strong> (« Sélectionner un dossier de projet existant ») et choisissez le dossier. Vous pouvez aussi saisir le chemin absolu dans le champ <strong>…ou saisir un chemin absolu</strong>, puis cliquer sur <strong>Ouvrir</strong>. Le projet s&#39;ouvre dans un onglet ; s&#39;il est déjà ouvert, son onglet est réactivé.</p><p>Si l&#39;ouverture échoue, un message préfixé « Erreur : » s&#39;affiche sous les actions, avec la raison donnée par le moteur (ou « Ouverture impossible. »).</p><h3 id="creer-un-workspace" tabindex="-1">Créer un workspace <a class="header-anchor" href="#creer-un-workspace" aria-label="Permalink to &quot;Créer un workspace&quot;">​</a></h3><p><strong>Créer…</strong> (« Initialiser un workspace dans un dossier ») vous fait choisir un dossier, l&#39;initialise en workspace Effortless et l&#39;ouvre aussitôt, sans autre question.</p><p><strong>Assistant de création</strong> est un bouton distinct : un parcours guidé en cinq étapes — projet, provider, stack, scaffold, déploiement. Voir <a href="/Effortless/guide/create.html">Assistant de création</a>.</p><h3 id="reprendre-un-projet-existant" tabindex="-1">Reprendre un projet existant <a class="header-anchor" href="#reprendre-un-projet-existant" aria-label="Permalink to &quot;Reprendre un projet existant&quot;">​</a></h3><p><strong>Reprendre un projet existant</strong> fait entrer dans Effortless un dépôt déjà en cours (« brownfield ») : vous choisissez son dossier, puis un assistant en quatre étapes s&#39;ouvre. Voir <a href="/Effortless/guide/adopt.html">Reprendre un projet existant</a>.</p><h3 id="rouvrir-un-recent" tabindex="-1">Rouvrir un récent <a class="header-anchor" href="#rouvrir-un-recent" aria-label="Permalink to &quot;Rouvrir un récent&quot;">​</a></h3><p>Cliquez sur une carte de la liste <strong>Récents</strong> pour rouvrir le workspace. Au survol d&#39;une carte, des contrôles apparaissent à sa droite :</p><ul><li>une liste déroulante pour ranger le projet dans une catégorie — seulement si vous avez déclaré au moins une catégorie ;</li><li><strong>✎</strong> (« Renommer (nom d&#39;affichage) ») : le nom devient un champ éditable. <strong>Enregistrer</strong> ou Entrée valide, <strong>Annuler</strong> ou Échap annule. Si vous videz le champ, le renommage est simplement annulé ;</li><li><strong>×</strong> retire le projet de la liste : « Retirer ? » demande confirmation, répondez <strong>Oui</strong> ou <strong>Non</strong>. Rien n&#39;est supprimé sur le disque.</li></ul><h3 id="classer-par-categories" tabindex="-1">Classer par catégories <a class="header-anchor" href="#classer-par-categories" aria-label="Permalink to &quot;Classer par catégories&quot;">​</a></h3><p><strong>Catégories</strong> (en haut à droite de la liste) ouvre la gestion des catégories :</p><ul><li>saisissez un nom dans <strong>Nouvelle catégorie</strong>, puis <strong>Ajouter</strong> ;</li><li>renommez une catégorie en modifiant son nom : le changement s&#39;enregistre quand vous quittez le champ ou appuyez sur Entrée ;</li><li>supprimez-la avec <strong>Supprimer la catégorie</strong>. Ses projets restent dans la liste, sans catégorie.</li></ul><p>Si un nom est refusé, l&#39;écran affiche « Catégorie non enregistrée (nom déjà pris ?). » Un projet se range dans une catégorie par la liste déroulante qui apparaît au survol de sa carte ; sans choix, il est dans « Sans catégorie ».</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>L&#39;agent n&#39;a pas de sélecteur : il travaille dans le dossier du workspace, résolu depuis son répertoire de travail. <code>effortless_init</code> crée un workspace, <code>effortless_status</code> en donne l&#39;état.</p>',21))])}const k=a(c,[["render",p]]);export{q as __pageData,k as default};
